    10	import java.util.List;
    11	
    12	/** Writes the PG refund batch file: one line per refund, TID TAB AMOUNT TAB merchant reference. */
    13	public final class RefundFileWriter {
    14	    private RefundFileWriter() {}
    15	
    16	    /**
    17	     * Merchant reference printed on the PG settlement file so finance can trace the refund to our order.
    18	     * It must differ per returned item: inside one batch the PG pays lines with the same TID, amount and
    19	     * reference only once, so the order number alone collapses two identical items into one refund.
    20	     */
    21	    public static String merchantRef(RefundLine line) {
    22	        return Refs.sanitize(line.orderNo() + "-" + line.lineNo());
    23	    }
    24	
    25	    public static String format(List<RefundLine> lines) {
    26	        StringBuilder sb = new StringBuilder();
    27	        for (RefundLine l : lines) {
    28	            sb.append(l.tid()).append('\t').append(l.amount()).append('\t').append(merchantRef(l)).append('\n');
    29	        }
    30	        return sb.toString();
    31	    }
    32	
    33	    public static Path write(Path dir, String batchId, List<RefundLine> lines) {
    34	        try {
    35	            Files.createDirectories(dir);
    36	            Path file = dir.resolve(batchId + ".tsv");
    37	            Files.writeString(file, format(lines), StandardCharsets.UTF_8);
    38	            return file;
    39	        } catch (IOException e) {
    40	            throw new IllegalStateException("cannot write refund batch " + batchId, e);
    41	        }
    42	    }
    43	}
===== src/util/Refs.java
     1	package util;
     2	
     3	/** Reference strings sent to the PG: [A-Za-z0-9-] only, at most 24 characters. */
     4	public final class Refs {
     5	    public static final int MAX = 24;
     6	
     7	    private Refs() {}
     8	
     9	    public static String sanitize(String raw) {
    10	        StringBuilder sb = new StringBuilder();
    11	        for (char c : raw.toCharArray()) {
    12	            if ((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '-') {
    13	                sb.append(c);
    14	            } else if (c == '_' || c == ' ' || c == '/') {
    15	                sb.append('-');
    16	            }
    17	        }
    18	        String s = sb.toString();
    19	        return s.length() > MAX ? s.substring(s.length() - MAX) : s;
    20	    }
    21	}
