    11	/** conf/app.properties, overridable by -Ddesk.KEY, DESK_KEY env vars, or {@link #with}. */
    12	public final class AppConfig {
    13	    private final Properties props = new Properties();
    14	    private final Map<String, String> overrides = new HashMap<>();
    15	
    16	    private AppConfig() {}
    17	
    18	    public static AppConfig load() {
    19	        return load(Path.of("conf", "app.properties"));
    20	    }
    21	
    22	    public static AppConfig load(Path file) {
    23	        AppConfig cfg = new AppConfig();
    24	        try (InputStream in = Files.newInputStream(file)) {
    25	            cfg.props.load(in);
    26	        } catch (IOException e) {
    27	            throw new IllegalStateException("cannot read config " + file, e);
    28	        }
    29	        return cfg;
    30	    }
    31	
    32	    /** Copy of this config with one key replaced (used by tests and the ops console). */
    33	    public AppConfig with(String key, String value) {
    34	        AppConfig copy = new AppConfig();
    35	        copy.props.putAll(props);
    36	        copy.overrides.putAll(overrides);
    37	        copy.overrides.put(key, value);
    38	        return copy;
    39	    }
    40	
    41	    public String get(String key) {
    42	        if (overrides.containsKey(key)) return overrides.get(key);
    43	        String sys = System.getProperty("desk." + key);
    44	        if (sys != null && !sys.isBlank()) return sys.trim();
    45	        String env = System.getenv("DESK_" + key.toUpperCase().replace('.', '_'));
    46	        if (env != null && !env.isBlank()) return env.trim();
    47	        String v = props.getProperty(key);
    48	        if (v == null) throw new IllegalStateException("missing config key " + key);
    49	        return v.trim();
    50	    }
