    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeFormatter;
    12	import java.util.ArrayList;
    13	import java.util.LinkedHashMap;
    14	import java.util.List;
    15	import java.util.Map;
    16	
    17	/**
    18	 * Nightly refund run: every pending refund line goes to the PG in batches of
    19	 * at most maxLines. Batch id = run id + chunk number; the PG settles and is
    20	 * reconciled per batch id.
    21	 */
    22	public class RefundBatchJob {
    23	    private final RefundRepository refunds;
    24	    private final PgsimClient pg;
    25	    private final String mid;
    26	    private final String prefix;
    27	    private final int maxLines;
    28	    private final Path workDir;
    29	
    30	    public RefundBatchJob(RefundRepository refunds, PgsimClient pg, String mid, String prefix, int maxLines,
    31	                          Path workDir) {
    32	        this.refunds = refunds;
    33	        this.pg = pg;
    34	        this.mid = mid;
    35	        this.prefix = prefix;
    36	        this.maxLines = maxLines;
    37	        this.workDir = workDir;
    38	    }
    39	
    40	    public RunResult run(LocalDate day) {
    41	        String runId = String.format("%s%s-%02d", prefix, day.format(DateTimeFormatter.BASIC_ISO_DATE),
    42	                refunds.nextRunSeq());
    43	        List<RefundLine> pending = new ArrayList<>();
    44	        for (RefundLine l : uniquePending()) {
    45	            // 결제일 당일분은 이번 회차에서 빼고 다음 날 회차로 (CS-4471)
    46	            // TODO: 이거 아직 필요한가? pgsim 4.x 올린 뒤로는 당일 건도 status·txn 다 정상으로 나옴
    47	            if (l.paidOn() != null && !l.paidOn().isBefore(day)) continue;
    48	            pending.add(l);
    49	        }
    50	        List<String> batchIds = new ArrayList<>();
    51	        int completed = 0;
    52	        for (int start = 0, chunk = 1; start < pending.size(); start += maxLines, chunk++) {
    53	            List<RefundLine> part = pending.subList(start, Math.min(pending.size(), start + maxLines));
    54	            String batchId = runId + "-" + chunk;
    55	            Path file = RefundFileWriter.write(workDir, batchId, part);
    56	            int accepted = pg.refund(mid, batchId, file);
    57	            if (accepted != part.size()) {
    58	                throw new IllegalStateException("PG accepted " + accepted + " of " + part.size() + " in " + batchId);
    59	            }
    60	            for (RefundLine l : part) l.submitted(batchId);
    61	            batchIds.add(batchId);
    62	            completed += RefundResultMatcher.apply(part, pg.status(batchId));
    63	        }
    64	        int awaiting = (int) pending.stream().filter(l -> l.status() == RefundLine.Status.SUBMITTED).count();
    65	        return new RunResult(runId, List.copyOf(batchIds), pending.size(), completed, awaiting);
    66	    }
    67	
    68	    /** A line queued twice by a CS double-click must be refunded once. */
    69	    private List<RefundLine> uniquePending() {
    70	        Map<String, RefundLine> byKey = new LinkedHashMap<>();
    71	        for (RefundLine l : refunds.pending()) {
    72	            byKey.putIfAbsent(l.orderNo() + "#" + l.lineNo(), l);
    73	        }
    74	        return new ArrayList<>(byKey.values());
    75	    }
    76	}
