    12	import java.util.concurrent.TimeUnit;
    13	
    14	/** Thin wrapper around the PG vendor CLI (vendor/bin/pgsim). One process per call. */
    15	public class PgsimClient {
    16	    /** What the PG reports for one payment. */
    17	    public record Txn(String tid, long amount, long refunded, long balance) {}
    18	
    19	    /** One row of a PG batch status: refund number, TID, amount, merchant field. */
    20	    public record RefundRow(String refundNo, String tid, long amount, String aux) {}
    21	
    22	    private final Path bin;
    23	    private final Path home;
    24	    private final long timeoutSeconds;
    25	
    26	    public PgsimClient(Path bin, Path home, long timeoutSeconds) {
    27	        this.bin = bin;
    28	        this.home = home;
    29	        this.timeoutSeconds = timeoutSeconds;
    30	    }
    31	
    32	    /** Charges the customer; returns the PG transaction id. */
    33	    public String pay(String mid, long amount, String orderNo) {
    34	        return run(List.of("pay", "--mid", mid, "--amt", Long.toString(amount), "--oid", orderNo)).strip();
    35	    }
    36	
    37	    /** Submits one refund batch file; returns the accepted count reported by the PG. */
    38	    public int refund(String mid, String batchId, Path file) {
    39	        String out = run(List.of("refund", "--mid", mid, "--batch", batchId, file.toString())).strip();
    40	        String[] t = out.split("\\s+");
    41	        if (t.length != 2 || !t[0].equals("accepted")) {
    42	            throw new PgException("unexpected refund reply: " + out);
    43	        }
    44	        return Integer.parseInt(t[1]);
    45	    }
    46	
    47	    public List<RefundRow> status(String batchId) {
    48	        List<RefundRow> rows = new ArrayList<>();
    49	        for (String line : run(List.of("status", "--batch", batchId)).split("\n")) {
    50	            if (line.isBlank()) continue;
    51	            String[] f = line.split("\t");
    52	            if (f.length != 4) throw new PgException("unexpected status line: " + line);
    53	            rows.add(new RefundRow(f[0], f[1], Long.parseLong(f[2]), f[3].equals("-") ? "" : f[3]));
    54	        }
    55	        return rows;
    56	    }
    57	
    58	    public Txn txn(String tid) {
    59	        Map<String, String> kv = new HashMap<>();
    60	        for (String line : run(List.of("txn", tid)).split("\n")) {
    61	            int sp = line.indexOf(' ');
    62	            if (sp > 0) kv.put(line.substring(0, sp), line.substring(sp + 1).strip());
    63	        }
    64	        return new Txn(kv.get("tid"), Long.parseLong(kv.get("amt")), Long.parseLong(kv.get("refunded")),
    65	                Long.parseLong(kv.get("bal")));
    66	    }
    67	
    68	    private String run(List<String> args) {
    69	        List<String> cmd = new ArrayList<>();
    70	        cmd.add(bin.toString());
    71	        cmd.addAll(args);
    72	        try {
    73	            Files.createDirectories(home);
    74	            ProcessBuilder pb = new ProcessBuilder(cmd);
    75	            pb.environment().put("PGSIM_HOME", home.toAbsolutePath().toString());
    76	            Process p = pb.start();
    77	            byte[] out;
    78	            byte[] err;
    79	            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
    80	                out = o.readAllBytes();
    81	                err = e.readAllBytes();
    82	            }
    83	            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
    84	                p.destroyForcibly();
    85	                throw new PgException("timeout: " + String.join(" ", cmd));
    86	            }
    87	            if (p.exitValue() != 0) {
    88	                throw new PgException("pgsim failed [" + new String(err, StandardCharsets.UTF_8).strip() + "]: "
    89	                        + String.join(" ", cmd));
    90	            }
    91	            return new String(out, StandardCharsets.UTF_8);
    92	        } catch (IOException e) {
    93	            throw new PgException("exec failed: " + e.getMessage());
    94	        } catch (InterruptedException e) {
    95	            Thread.currentThread().interrupt();
    96	            throw new PgException("interrupted");
    97	        }
    98	    }
    99	
   100	    public static class PgException extends RuntimeException {
   101	        public PgException(String msg) {
   102	            super(msg);
   103	        }
   104	    }
   105	}
