    15	
    16	    /**
    17	     * Merchant reference printed on the PG settlement file so finance can trace the refund to our order.
    18	     * It must differ per returned item: inside one batch the PG pays lines with the same TID, amount and
    19	     * reference only once, so the order number alone collapses two identical items into one refund.
    20	     */
    21	    public static String merchantRef(RefundLine line) {
    22	        return Refs.sanitize(line.orderNo() + "-" + line.lineNo());
    23	    }
