    25	    public static String format(List<RefundLine> lines) {
    26	        StringBuilder sb = new StringBuilder();
    27	        for (RefundLine l : lines) {
    28	            sb.append(l.tid()).append('\t').append(l.amount()).append('\t').append(merchantRef(l)).append('\n');
    29	        }
    30	        return sb.toString();
    31	    }
