    34	        try {
    35	            Files.createDirectories(dir);
    36	            Path file = dir.resolve(batchId + ".tsv");
    37	            Files.writeString(file, format(lines), StandardCharsets.UTF_8);
    38	            return file;
    39	        } catch (IOException e) {
