    14	/** Customer-facing refund statement. Money figures come from the PG, not from our own bookkeeping. */
    15	public class CustomerStatementService {
    16	    private final OrderRepository orders;
    17	    private final RefundRepository refunds;
    18	    private final PgsimClient pg;
    19	
    20	    public CustomerStatementService(OrderRepository orders, RefundRepository refunds, PgsimClient pg) {
    21	        this.orders = orders;
    22	        this.refunds = refunds;
    23	        this.pg = pg;
    24	    }
    25	
    26	    public CustomerStatement statement(String orderNo) {
    27	        Order order = orders.find(orderNo).orElseThrow(() -> new IllegalArgumentException("no order " + orderNo));
    28	        PgsimClient.Txn txn = pg.txn(order.tid());
    29	        List<RefundLine> mine = refunds.byOrder(orderNo);
    30	        List<CustomerStatement.Line> lines = new ArrayList<>();
    31	        for (OrderLine ol : order.lines()) {
    32	            RefundLine r = mine.stream().filter(x -> x.lineNo() == ol.lineNo()).findFirst().orElse(null);
    33	            String state = r == null ? "구매" : switch (r.status()) {
    34	                case REQUESTED -> "환불 접수";
    35	                case SUBMITTED -> "환불 처리 중";
    36	                case DONE -> "환불 완료";
    37	            };
    38	            lines.add(new CustomerStatement.Line(ol.lineNo(), ol.name(), ol.paid(), state,
    39	                    r == null ? null : r.refundNo()));
    40	        }
    41	        return new CustomerStatement(orderNo, order.customerId(), txn.amount(), txn.refunded(), txn.balance(),
    42	                List.copyOf(lines));
    43	    }
    44	}
