    15	public class CheckoutService {
    16	    private final Map<String, CatalogItem> catalog;
    17	    private final OrderRepository orders;
    18	    private final PgsimClient pg;
    19	    private final String mid;
    20	
    21	    public CheckoutService(Map<String, CatalogItem> catalog, OrderRepository orders, PgsimClient pg, String mid) {
    22	        this.catalog = catalog;
    23	        this.orders = orders;
    24	        this.pg = pg;
    25	        this.mid = mid;
    26	    }
    27	
    28	    /** One line per unit: ordering the same SKU twice gives two lines. */
    29	    public Order place(String customerId, List<String> skus, long coupon, LocalDate day) {
    30	        if (skus.isEmpty()) throw new IllegalArgumentException("empty cart");
    31	        List<CatalogItem> items = new ArrayList<>();
    32	        for (String sku : skus) {
    33	            CatalogItem item = catalog.get(sku);
    34	            if (item == null) throw new IllegalArgumentException("unknown sku " + sku);
    35	            items.add(item);
    36	        }
    37	        List<Long> discounts = DiscountAllocator.allocate(items.stream().map(CatalogItem::price).toList(), coupon);
    38	        List<OrderLine> lines = new ArrayList<>();
    39	        for (int i = 0; i < items.size(); i++) {
    40	            CatalogItem it = items.get(i);
    41	            lines.add(new OrderLine(i + 1, it.sku(), it.name(), it.price(), discounts.get(i)));
    42	        }
    43	        String orderNo = orders.nextOrderNo(day.format(DateTimeFormatter.BASIC_ISO_DATE));
    44	        long total = lines.stream().mapToLong(OrderLine::paid).sum();
    45	        String tid = pg.pay(mid, total, orderNo);
    46	        Order order = new Order(orderNo, customerId, tid, List.copyOf(lines), coupon, day);
    47	        orders.save(order);
    48	        return order;
    49	    }
    50	}

