    14	/** Customer-facing refund statement. Money figures come from the PG, not from our own bookkeeping. */
    15	public class CustomerStatementService {
    16	    private final OrderRepository orders;
    17	    private final RefundRepository refunds;
    18	    private final PgsimClient pg;
    19	
    20	    public CustomerStatementService(OrderRepository orders, RefundRepository refunds, PgsimClient pg) {
    21	        this.orders = orders;
    22	        this.refunds = refunds;
    23	        this.pg = pg;
    24	    }
