import api.RefundDeskApi;
import domain.CustomerStatement;
import domain.Order;
import domain.RunResult;
import java.time.LocalDate;
import java.util.List;

public class SameDayCheck {
    public static void main(String[] a) throws Exception {
        LocalDate d = LocalDate.of(2026, 10, 8);
        RefundDeskApi api = new RefundDeskApi(TestSupport.sandbox());
        Order o = api.placeOrder("C-9", List.of("SKU-EARB", "SKU-CASE"), 0, d);
        String id = api.refundNow(o.orderNo(), List.of(1), d);
        CustomerStatement s = api.statement(o.orderNo());
        System.out.println("same-day id=" + id + " refunded=" + s.refunded() + " state=" + s.lines().get(0).state());
        RunResult night = api.runRefunds(d);
        System.out.println("night of payment day submitted=" + night.submitted());
        RunResult next = api.runRefunds(d.plusDays(1));
        System.out.println("next day submitted=" + next.submitted() + " batches=" + next.batchIds());
        System.out.println("after next run refunded=" + api.statement(o.orderNo()).refunded() + " state=" + api.statement(o.orderNo()).lines().get(0).state());
    }
}
